import sys
from collections import defaultdict

def max_value_and_signs(H, W, N, grid, particles):
    adjacents = defaultdict(list)
    for i in range(N):
        y, x, _ = particles[i]
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ny, nx = y + dy, x + dx
            for j in range(i + 1, N):
                ny2, nx2, _ = particles[j]
                if (ny, nx) == (ny2, nx2):
                    adjacents[i].append(j)
                    adjacents[j].append(i)

    def dfs(node, visited, sign):
        visited[node] = sign
        result = sign * particles[node][2] * grid[particles[node][0] - 1][particles[node][1] - 1]
        for neighbor in adjacents[node]:
            if visited[neighbor] == 0:
                result += dfs(neighbor, visited, -sign)
        return result

    visited = [0] * N
    total_value = 0
    signs = [0] * N

    for i in range(N):
        if visited[i] == 0:
            pos_value = dfs(i, visited, 1)
            neg_value = dfs(i, visited, -1)
            if pos_value >= neg_value:
                total_value += pos_value
                for j in range(N):
                    if visited[j] == 1:
                        signs[j] = 1
                    elif visited[j] == -1:
                        signs[j] = -1
            else:
                total_value += neg_value
                for j in range(N):
                    if visited[j] == -1:
                        signs[j] = 1
                    elif visited[j] === 1:
                        signs[j] = -1

    return total_value, signs

input = sys.stdin.read().split()
index = 0
T = int(input[index])
index += 1
results = []

for _ in range(T):
    H = int(input[index])
    W = int(input[index + 1])
    N = int(input[index + 2])
    index += 3
    grid = []
    for _ in range(H):
        row = list(map(int, input[index:index + W]))
        grid.append(row)
        index += W
    particles = []
    for _ in range(N):
        y = int(input[index])
        x = int(input[index + 1])
        p = int(input[index + 2])
        particles.append((y, x, p))
        index += 3
    value, signs = max_value_and_signs(H, W, N, grid, particles)
    results.append(f"{value}\n{' '.join(map(str, signs))}")

print("\n".join(results))
